const labels:Record<string,string> = {id:'Постоянный ID',name:'Название / рабочее имя',status:'Состояние',source:'Источник',details:'Реквизиты и дополнительные сведения',organization_id:'Organization MAX',inn:'ИНН',legal_form:'Форма лица',number:'Номер договора',contract_id:'Договор',revision:'Номер редакции',signed_on:'Дата подписания',effective_from:'Действует с',effective_to:'Действует до',basis:'Документ-основание',party_snapshots:'Снимки сторон и договорные роли',code:'Код работы',parent_id:'Родительская работа',unit_id:'Единица измерения',photo_work_type_id:'Сопоставление с фототегом MAX',area_id:'Территория АРМ',territory_id:'Договорная территория',replaced_by_id:'Заменена клеткой',cell_id:'Клетка АРМ',resource_id:'Wialon resource_id',zone_id:'Wialon zone_id',district_id:'Геозона MAX',plate:'Государственный номер',vehicle_type:'Тип техники',model:'Марка / модель',calibration_m3:'Тарировка, м³',calibration_on:'Дата подтверждения тарировки',wialon_unit_id:'Wialon unit ID',vehicle_id:'Машина',counterparty_id:'Контрагент',role:'Роль связи',valid_from:'Начало действия',valid_to:'Окончание действия',evidence_id:'Подтверждающий документ',object_id:'Договорный объект DO',site_id:'Площадка PL',sha256:'SHA-256',location:'Расположение оригинала',revision_id:'Редакция договора',kind:'Тип приложения',document_id:'Документ',work_id:'Договорная работа',stage:'Этап',period_from:'Начало периода',period_to:'Конец периода',source_row:'Исходная строка приложения'};
Object.assign(labels,{indicator:'Физический показатель',quantity_text:'Объём по источнику',rate_text:'Цена единицы по источнику',total_text:'Сумма по источнику'});
