function StatusBadge({status}:{status:string}){
  return <span className={`nsi-status ${status.toLowerCase()}`}>{statuses[status]??status}</span>;
}

function rowFacts(kind:string,row:RecordData){
  const keys = kind==='vehicles'?['plate','vehicle_type','model']:kind==='counterparties'?['inn','legal_form']:kind==='contracts'?['number']:kind==='contract-lines'?['indicator','quantity_text','rate_text']:kind==='territories'?['area_id']:kind==='works'?['code']:[];
  return keys.map(key=>row[key]).filter(value=>value!==null&&value!==undefined&&value!=='').map(String).slice(0,3);
}

type VehicleSort = 'name'|'plate'|'type'|'owner'|'control';
type VehicleGroup = ''|'type'|'owner'|'control';
type Ownership = {current:RecordData|null;candidates:RecordData[];history:RecordData[]};
type Capability = RecordData&{selected:boolean};
type ApprovalDecision = RecordData&{vehicle_id:string;vehicle_name:string;plate?:string;decision:string};
type ApprovalRequest = RecordData&{letter_number:string;letter_date:string;request_document_id:string;response_document_id?:string;decisions:ApprovalDecision[]};
type CalibrationReadiness = {ready:boolean;reasons:{code:string;message:string}[];document_id?:string;volume_m3?:string;verified_at?:string;verified_by?:string};
type QuestionnaireEvent = {outcome:string;message:string;entity?:string;record_id?:string;resolved?:boolean;resolution?:string;resolved_at?:string;field_kind?:string;field_label?:string;current_value?:unknown;applied_values?:Record<string,unknown>|null};
type QuestionnaireIssue = {field:string;message:string};
type QuestionnaireDocument = {id?:string;key?:string;original_name?:string;declared_name?:string;kind:string;state?:string;status?:string;vehicle_key?:string};
type QuestionnaireItem = {key:string;section:string;source_row?:number;record_id?:string;current?:Record<string,unknown>|null;proposed:Record<string,unknown>;accepted:Record<string,unknown>;operation?:string;status:string;issues:QuestionnaireIssue[];documents?:QuestionnaireDocument[]};
type QuestionnaireSummary = {schema_version?:number;accepted?:number;review?:number;events?:QuestionnaireEvent[];counterparty?:QuestionnaireItem;vehicles?:QuestionnaireItem[];unassigned_documents?:QuestionnaireDocument[];journal?:{message:string}[];counts?:{source_rows:number;prepared:number;applied:number;pending:number;issues:number;unassigned_documents:number}};
type QuestionnaireImport = {id:string;file_name:string;status:string;received_at:string;counterparty_id?:string;summary:QuestionnaireSummary};
const ownerName=(row:RecordData)=>String(row.operational_owner||(row.owner_candidate?`Кандидат: ${row.owner_candidate}`:'Не назначен'));
const controlName=(row:RecordData)=>row.wialon_control==='MATCHED'?'Есть Wialon':'Нет Wialon';
const groupName=(row:RecordData,group:VehicleGroup)=>group==='type'?String(row.vehicle_type):group==='owner'?ownerName(row):group==='control'?controlName(row):'';

function VehicleTable({rows,onOpen,sort='name',group='',onSort}:{rows:RecordData[];onOpen:(id:string)=>void;sort?:VehicleSort;group?:VehicleGroup;onSort?:(sort:VehicleSort)=>void}){
  const header=(key:VehicleSort,label:string)=><button type="button" onClick={()=>onSort?.(key)}>{label}{sort===key&&<span aria-hidden="true"> ↑</span>}</button>;
  return <div className="nsi-table-wrap"><table className="nsi-table nsi-vehicle-table"><thead><tr><th>{header('name','Рабочее имя')}</th><th>{header('plate','Госномер')}</th><th>{header('type','Тип')}</th><th>{header('owner','Операционный владелец')}</th><th>{header('control','Контроль')}</th><th aria-label="Открыть"/></tr></thead><tbody>{rows.map((row,index)=>{const label=groupName(row,group),previous=index?groupName(rows[index-1],group):'';return <Fragment key={row.id}>{group&&label!==previous&&<tr className="nsi-group-row"><td colSpan={6}>{label}<span>{rows.filter(item=>groupName(item,group)===label).length}</span></td></tr>}<tr onClick={()=>onOpen(row.id)}><td>{row.short_name?<strong>{String(row.short_name)}</strong>:<><strong className="nsi-missing-name">Короткое имя не назначено</strong><small>Назначить для {String(row.plate)}</small></>}</td><td><strong>{String(row.plate)}</strong></td><td>{String(row.vehicle_type)}</td><td>{row.operational_owner?<strong>{String(row.operational_owner)}</strong>:<><span className="nsi-muted">Не назначен</span>{row.owner_candidate&&<small>Кандидат: {String(row.owner_candidate)}</small>}</>}</td><td><span className={`nsi-control ${row.wialon_control==='MATCHED'?'ok':'warn'}`}>{row.wialon_control==='MATCHED'?'Wialon сопоставлен':'Нет Wialon ID'}</span></td><td><ChevronRight size={18}/></td></tr></Fragment>})}</tbody></table>{!rows.length&&<div className="nsi-empty"><Truck size={28}/><strong>Техника не найдена</strong><span>Сбросьте один из фильтров.</span></div>}</div>;
}

function QuestionnaireDataReview({batch,onPrepare,onAssign,onApply,busy}:{batch:QuestionnaireImport;onPrepare:(item:QuestionnaireItem,accepted:Record<string,unknown>)=>void;onAssign:(document:QuestionnaireDocument,vehicleKey:string,kind:string)=>void;onApply:()=>void;busy:boolean}){
  const items=[...(batch.summary.counterparty?[batch.summary.counterparty]:[]),...(batch.summary.vehicles??[])];
  const storageKey=`contractor-questionnaire-drafts:${batch.id}`;
  const [drafts,setDrafts]=useState<Record<string,Record<string,unknown>>>(()=>{try{return JSON.parse(sessionStorage.getItem(storageKey)||'{}');}catch{return {};}});
  const [documentDrafts,setDocumentDrafts]=useState<Record<string,{vehicleKey:string;kind:string}>>({});
  useEffect(()=>{sessionStorage.setItem(storageKey,JSON.stringify(drafts));},[storageKey,drafts]);
  const values=(item:QuestionnaireItem)=>drafts[item.key]??item.accepted??item.proposed;
  const setValue=(item:QuestionnaireItem,key:string,value:unknown)=>setDrafts({...drafts,[item.key]:{...values(item),[key]:value}});
  const status=(item:{status?:string})=>item.status==='APPLIED'?'Записано в НСИ':item.status==='STAGED'?'Подготовлено':'Требует решения';
  const compare=(item:QuestionnaireItem,fields:string[])=><div className="nsi-object-fields"><div className="nsi-reconcile-head"><span>Поле НСИ</span><span>Текущее значение</span><span>Предложено анкетой</span><span>Принимаемое значение</span></div>{fields.map(key=><div className="nsi-object-field" key={key}><strong>{labels[key]??key}</strong><span>{String(item.current?.[key]??'—')}</span><span>{String(item.proposed[key]??'—')}</span><input aria-label={`${labels[key]??key} строка ${item.source_row??''}`} disabled={item.status==='APPLIED'} value={String(values(item)[key]??'')} onChange={event=>setValue(item,key,event.target.value)}/></div>)}</div>;
  const itemCard=(item:QuestionnaireItem)=><article className={`nsi-review-object ${item.status.toLowerCase()}`} key={item.key} id={item.key}><header><div><span>{item.section==='vehicles'?`Строка ${item.source_row}`:'Паспорт контрагента'}</span><h3>{item.section==='vehicles'?String(values(item).name||values(item).plate||'Машина без имени'):String(values(item).name||'Контрагент')}</h3></div><span className="nsi-control">{status(item)}</span></header>{item.issues.length?<ul className="nsi-object-issues">{item.issues.map((issue,index)=><li key={index}><strong>{labels[issue.field]??issue.field}</strong>{issue.message}</li>)}</ul>:<p className="nsi-no-differences">Системный контроль пройден, явных замечаний нет.</p>}{compare(item,item.section==='vehicles'?['name','plate','vehicle_type','model','calibration_m3']:['name','inn','legal_form'])}{item.section==='vehicles'&&<div className="nsi-row-documents"><strong>Документы этой машины</strong>{item.documents?.length?item.documents.map((document,index)=><a key={index} target="_blank" rel="noreferrer" href={`/api/contractor/questionnaire-imports/${encodeURIComponent(batch.id)}/documents/${encodeURIComponent(document.id??'')}`}>{document.kind==='STS'?'СТС':'Тарировка'}: {document.state==='MISSING'?<em>файл отсутствует</em>:document.original_name}</a>):<span>Документы в строке не указаны</span>}</div>}<footer>{item.record_id&&<Link to={`/contractor/${item.section==='vehicles'?'vehicles':'counterparties'}/${encodeURIComponent(item.record_id)}?returnQuestionnaire=${encodeURIComponent(batch.id)}&item=${encodeURIComponent(item.key)}`}>Открыть текущую карточку НСИ</Link>}<button className="primary" disabled={busy||item.status==='APPLIED'} onClick={()=>onPrepare(item,values(item))}>{item.status==='STAGED'?'Обновить подготовленную строку':'Сохранить строку'}</button></footer></article>;
  const unassigned=batch.summary.unassigned_documents??[];
  return <section className="nsi-data-review"><Link className="nsi-back" to="/contractor/questionnaires">← Все анкеты</Link><header><div><h2>Проверка и принятие данных НСИ</h2><p>{batch.file_name} · одна анкета, три рабочих блока</p></div><span>{batch.summary.counts?.pending??0} строк требуют решения</span></header><div className="nsi-review-summary"><span><strong>{batch.summary.counts?.source_rows??0}</strong> исходных строк техники</span><span><strong>{batch.summary.counts?.issues??0}</strong> замечаний</span><span><strong>{batch.summary.counts?.prepared??0}</strong> подготовлено</span><span><strong>{batch.summary.counts?.applied??0}</strong> записано в НСИ</span></div><section className="nsi-review-block"><h2>Контрагент</h2>{batch.summary.counterparty&&itemCard(batch.summary.counterparty)}</section><section className="nsi-review-block"><h2>Техника <span>{batch.summary.vehicles?.length??0}</span></h2>{batch.summary.vehicles?.map(itemCard)}</section><section className="nsi-review-block"><h2>Непривязанные документы <span>{unassigned.length}</span></h2>{unassigned.length?unassigned.map(document=>{const draft=documentDrafts[document.key??'']??{vehicleKey:document.vehicle_key??'',kind:document.kind==='OTHER'?'STS':document.kind};return <article className="nsi-unassigned-document" key={document.key}><div><strong>{document.original_name}</strong><a target="_blank" rel="noreferrer" href={`/api/contractor/questionnaire-imports/${encodeURIComponent(batch.id)}/documents/${encodeURIComponent(document.id??'')}`}>Открыть документ</a></div><select value={draft.kind} onChange={event=>setDocumentDrafts({...documentDrafts,[document.key??'']:{...draft,kind:event.target.value}})}><option value="STS">СТС</option><option value="CALIBRATION">Тарировка</option><option value="OTHER">Другой документ</option></select><select value={draft.vehicleKey} onChange={event=>setDocumentDrafts({...documentDrafts,[document.key??'']:{...draft,vehicleKey:event.target.value}})}><option value="">Выберите машину</option>{batch.summary.vehicles?.map(vehicle=><option key={vehicle.key} value={vehicle.key}>{String(vehicle.accepted.name||vehicle.accepted.plate)} · строка {vehicle.source_row}</option>)}</select><button disabled={busy||!draft.vehicleKey||document.status==='APPLIED'} onClick={()=>onAssign(document,draft.vehicleKey,draft.kind)}>{document.status==='STAGED'?'Обновить привязку':'Подготовить привязку'}</button></article>}):<p className="nsi-no-differences">Все файлы однозначно связаны со строками техники.</p>}</section><details className="nsi-history"><summary>Журнал импорта</summary>{batch.summary.journal?.map((entry,index)=><p key={index}>{entry.message}</p>)}</details><footer className="nsi-accept-questionnaire"><div><strong>Принять подготовленные данные</strong><small>В НСИ попадут только сохранённые строки. Остальные сохранятся в этой анкете для продолжения работы.</small></div><button className="primary" disabled={busy||!(batch.summary.counts?.prepared)} onClick={onApply}>{busy?'Применение…':`Применить · ${batch.summary.counts?.prepared??0}`}</button></footer></section>;
}

function QuestionnaireDataReviewLegacy({batch}:{batch:QuestionnaireImport;values:Record<number,string>;staged:Set<number>;onValue:(index:number,value:string)=>void;onStage:(index:number)=>void;onApply:()=>void;busy:boolean}){
  return <section className="nsi-data-review"><Link className="nsi-back" to="/contractor/questionnaires">← Все анкеты</Link><header><div><h2>Архивный протокол загрузки</h2><p>{batch.file_name}</p></div><span>Создан прежней версией обработчика</span></header><p>Для объектного разбора загрузите актуальную полную анкету повторно. Ранее внесённые сведения НСИ сохранены.</p><details className="nsi-history" open><summary>События прежнего импорта</summary>{batch.summary.events?.map((event,index)=><p key={index}>{event.message}</p>)}</details></section>;
}

function StructuredValue({value}:{value:unknown}) {
  if(value===null||value===undefined||value==='')return <>—</>;
  if(Array.isArray(value))return <ol>{value.map((v,i)=><li key={i}><StructuredValue value={v}/></li>)}</ol>;
  if(typeof value==='object')return <dl className="nsi-properties">{Object.entries(value).map(([k,v])=><div key={k}><dt>{labels[k]??k}</dt><dd><StructuredValue value={v}/></dd></div>)}</dl>;
  return <>{String(value)}</>;
}

function DetailsEditor({value,onChange,legal,section}:{value:string;onChange:(value:string)=>void;legal:boolean;section:string}){
  let data:Record<string,unknown>={};try{data=JSON.parse(value||'{}');}catch{return <p>Не удалось прочитать дополнительные сведения.</p>;}
  const fields=legal?['Организационно-правовая форма','Полное наименование юридического лица','Краткое наименование','ИНН','КПП (для юрлица, если есть)','ОГРН / ОГРНИП','Юридический / регистрационный адрес','Почтовый адрес','Телефон','Электронная почта','ФИО подписанта','Должность подписанта','Основание полномочий','Наименование банка','БИК','Расчётный счёт','Корреспондентский счёт']:[];
  const listKey=section==='bank'?'Банковские счета':'Представители';
  const listFields=section==='bank'?['Банк','БИК','Расчётный счёт','Корреспондентский счёт']:['ФИО','Должность','Основание полномочий','Телефон','Электронная почта'];
  const list=Array.isArray(data[listKey])?data[listKey] as Record<string,string>[]:[];
  return <div className="nsi-properties">{[...new Set([...fields,...Object.keys(data)])].filter(k=>!['Банковские счета','Представители'].includes(k)&&(!legal||legalSection(k)===section)).map(k=><label key={k}>{labels[k]??k}{typeof data[k]==='object'&&data[k]!==null?<StructuredValue value={data[k]}/>:<input value={String(data[k]??'')} onChange={e=>onChange(JSON.stringify({...data,[k]:e.target.value}))}/>}</label>)}
    {legal&&['bank','contacts'].includes(section)&&<section><h4>{listKey}</h4>{list.map((row,index)=><fieldset key={index}><legend>{index+1}</legend>{listFields.map(key=><label key={key}>{key}<input value={row[key]??''} onChange={e=>onChange(JSON.stringify({...data,[listKey]:list.map((r,i)=>i===index?{...r,[key]:e.target.value}:r)}))}/></label>)}</fieldset>)}<button type="button" onClick={()=>onChange(JSON.stringify({...data,[listKey]:[...list,{}]}))}>Добавить {section==='bank'?'счёт':'представителя'}</button></section>}
  </div>;
}

function legalSection(key:string){
  if(key==='Представители')return 'contacts';
  if(/банк|бик|счёт|счет/i.test(key))return 'bank';
  if(/телефон|почта|подписант|должность|полномочи|контакт/i.test(key))return 'contacts';
  return 'requisites';
}

function PartiesEditor({value,onChange}:{value:string;onChange:(value:string)=>void}){
  let data:Record<string,string>[]=[];try{data=JSON.parse(value||'[]');}catch{return <p>Не удалось прочитать стороны.</p>;}
  const save=(next:Record<string,string>[])=>onChange(JSON.stringify(next));
  return <div>{data.map((party,i)=><fieldset key={i}><legend>Сторона {i+1}</legend>{['name','role','inn','address','signer','authority'].map(k=><label key={k}>{({name:'Наименование',role:'Договорная роль',inn:'ИНН',address:'Адрес',signer:'Подписант',authority:'Основание полномочий'} as Record<string,string>)[k]}<input value={party[k]??''} onChange={e=>save(data.map((p,j)=>i===j?{...p,[k]:e.target.value}:p))}/></label>)}</fieldset>)}<button type="button" onClick={()=>save([...data,{name:'',role:''}])}>Добавить сторону</button></div>;
}

