  const [calibrationVolumes,setCalibrationVolumes] = useState<Record<string,string>>({});
  const [capabilities,setCapabilities] = useState<Capability[]>([]);
  const [questionnaireImports,setQuestionnaireImports] = useState<QuestionnaireImport[]>([]), [questionnaireFile,setQuestionnaireFile] = useState<File|null>(null), [showQuestionnaireImports,setShowQuestionnaireImports] = useState(false);
  const [questionnaireBatch,setQuestionnaireBatch] = useState<QuestionnaireImport|null>(null), [questionnaireResolutions,setQuestionnaireResolutions] = useState<Record<number,string>>({});
  const [stagedQuestionnaireRows,setStagedQuestionnaireRows] = useState<Set<number>>(new Set());
